const SCL = 3;
let PENS = ["cyan", "deeppink"];
let R, D;
let pal, BG;

function setup() {
	createCanvas(297 * SCL, 210 * SCL); // createCanvas(windowWidth, windowHeight);
	R = max(width, height) * 0.465;
	describe("horizontal lines with oscilator");
	pixelDensity(1);
	frameRate(15);
	noFill();
	strokeWeight(3);

	const seed = ~~random(987654321);
	noiseSeed(seed);
	randomSeed(seed);
	console.log(`seed: ${seed}`);

	pal = [...random(palettes)];
	shuffle(pal, true);
	BG = pal.splice(~~random(pal.length), 1)[0];
	PENS = [];
	shuffle(pal, true);	PENS.push(pal.splice(~~random(pal.length), 1)[0]);
	shuffle(pal, true);	PENS.push(pal.splice(~~random(pal.length), 1)[0]);
	// console.log(BG, pal)

	loop();
}

function draw() {
	background(240); // BG
	translate(width/2, height/2);

	// svg
	svgStr = ``; svgGr = []; for (let i = 0; i < PENS.length; i++) svgGr[i] = ``;

	const RQ = (noise(frameCount/60, 42)*7.5);
	D = R / (noise(23, frameCount/120)*23);

	for (let y = -(~~(height/2)), i = 0; y < height/2; y += 1*SCL, i++) {
		stroke(PENS[i%PENS.length]);

		beginShape();
		svgStr = `<polyline points="`;
		for (let x = -(~~(width/2)); x < width/2; x += SCL) {
			//
			let xx = x, yy = y;
			const dst = dist(x, y, 0, 0);
			let f = dst < R ? abs(1-dst/R) : 0;
			const amp = map(y, -height/2, height/2, 1, R/RQ);
			const offX = map(y, -height/2, height/2, 0, -D*2*TAU);

			if ((i%PENS.length) === 0) {
				// blue
				f = pow(f, 1.5); // f = 1 - pow(f, 2)
				yy += cos(map(x+offX, -width/2, width/2, 0, PI)) * max(abs(R-dst), R) * 0.9 * f;
			} else if ((i%PENS.length) === 1) {
				// red
				f = pow(f, 1.5);
				yy += sin((x+offX)/D) * amp * f;
			}

			vertex (xx, yy);
			svgStr += `${nf(xx+width/2, 0, 2)},${nf(yy+height/2, 0, 2)} `;
		}
		endShape();

		svgStr += `" />\n`;
		svgGr[i%PENS.length] += svgStr;
	}

	// svg
	svgStr = ``;


	// // noLoop() removed for animation
}

